CREATE TABLE IF NOT EXISTS schemes (
    id SERIAL PRIMARY KEY,
    scheme_code VARCHAR(30) UNIQUE NOT NULL,
    scheme_name VARCHAR(255) NOT NULL,
    category VARCHAR(50) NOT NULL,
    grant_amount VARCHAR(100) NOT NULL,
    max_income_limit DECIMAL(10,2),
    eligible_categories VARCHAR(100),
    min_age INT,
    max_age INT,
    required_documents TEXT,
    description TEXT
);

ON CONFLICT (scheme_code) DO UPDATE SET 
    scheme_name = EXCLUDED.scheme_name,
    category = EXCLUDED.category,
    grant_amount = EXCLUDED.grant_amount,
    max_income_limit = EXCLUDED.max_income_limit,
    eligible_categories = EXCLUDED.eligible_categories,
    min_age = EXCLUDED.min_age,
    max_age = EXCLUDED.max_age,
    required_documents = EXCLUDED.required_documents,
    description = EXCLUDED.description;
